// ============================================================
// logo_rom_eram.v  --  P1b: Logo 调色板索引 ROM（同步读，推断 ERAM）
//
// 由 tools/gen_logo_rom_v.py 自动生成，请勿手工修改。
//   logo_pixel.mif  : 13724 x 8bit 索引（0 = 透明）
//   几何            : 146x94 @(7,34)  深度=13724
//   实际用到颜色数  : 252  最大索引=255
//
// ⚠ 端口延迟：O_idx 比 I_addr 晚 2 拍（addr_reg -> case -> idx_reg）
//    调用方必须把 osd_hit / 坐标 / 视频数据对齐到同一拍。
//
// 与旧的 anlogic_logo_rom 的区别（这是 P1b 的核心）：
//    旧：always @(*) case(...) 组合输出 => 综合成巨型 LUT 网，
//        实测占 HDMI_PIXEL_CLK 域最差路径约 6.1 ns / 12 级 LUT。
//    新：地址与输出都打拍 => case 被放进 ERAM，组合链被切断。
//
// ERAM 硬性约束（PH1P 用户手册）：地址与数据输入必须与输入时钟同步，
// 否则工具不做时序分析、ERAM 内容可能不可预测地翻转 => 必须同步读。
// ============================================================

module logo_rom_eram (
    input  wire              I_clk,
    input  wire              I_rst_n,
    input  wire [13:0]  I_addr,
    output reg  [7:0]   O_idx
);

    // ---- 地址打一拍：ERAM 要求地址同步 ----
    reg [13:0] addr_reg;
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) addr_reg <= {14{1'b0}};
        else         addr_reg <= I_addr;
    end

    // ---- 同步读：寄存输出直接由常量 case 赋值 ----
    // 注意：属性必须作用在"被时序块赋值的寄存器"上，
    // 加在组合 always 块上无效（综合器不会推断 ERAM）。
    (* ram_style = "block" *)
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin
            O_idx <= {8{1'b0}};
        end else begin
            case(addr_reg)
                14'd0: O_idx <= 8'h00;
                14'd1: O_idx <= 8'h00;
                14'd2: O_idx <= 8'h00;
